+using System.Data;
 using System.Web;
 using System.Web.UI;
-using System.Web.UI.WebControls;
+using InformationWebObject;

 namespace InformationWeb.Controls
 {
     public partial class Banner : System.Web.UI.UserControl
     {
-      
         protected void Page_Load(object sender, EventArgs e)
         {
-           
+            if (!Page.IsPostBack)
+            {
+                LoadBannerData();
+            }
+        }
+        private void LoadBannerData()
+        {
+            INFO_Information info = new INFO_Information();
+            DataTable dt = info.GetDataTable("INFO_Information_Banner");
+            if (dt != null && dt.Rows.Count > 0)
+            {
+                rptBanner.DataSource = dt;
+                rptBanner.DataBind();
+                bannerWrapper.Visible = true;
+            }
+            else
+            {
+                bannerWrapper.Visible = false;
+            }
+        }
+        protected string GetBannerImage(object imageUrl, object title)
+        {
+            if (imageUrl == null || string.IsNullOrEmpty(imageUrl.ToString()))
+            {
+                return string.Empty;
+            }
+            string imgUrl = imageUrl.ToString();
+            if (!imgUrl.StartsWith("http") && !imgUrl.StartsWith("/"))
+            {
+                imgUrl = DCore.Globals.ApplicationVRoot + "/" + imgUrl.TrimStart('/');
+            }
+            string titleText = title == null ? string.Empty : HttpUtility.HtmlAttributeEncode(title.ToString());
+            return string.Format("<img src=\"{0}\" alt=\"{1}\" title=\"{1}\" />", imgUrl, titleText);
+        }
+        protected string GetBannerImageUrl(object row)
+        {
+            if (row == null)
+            {
+                return string.Empty;
+            }
+            DataRowView drv = row as DataRowView;
+            if (drv == null)
+            {
+                return string.Empty;
+            }
+            string id = drv.Row.Table.Columns.Contains("InformationID") ? Convert.ToString(drv["InformationID"]) : string.Empty;
+            string image = drv.Row.Table.Columns.Contains("ThumbImage") ? Convert.ToString(drv["ThumbImage"]) : string.Empty;
+            if (string.IsNullOrEmpty(image))
+            {
+                return string.Empty;
+            }
+            if (image.StartsWith("http") || image.StartsWith("/"))
+            {
+                return image;
+            }
+            string paddedId = "000000" + id;
+            string subFolder = "Information" + paddedId.Substring(paddedId.Length - 6);
+            return WebGlobal.InformationThumbDirectory + "/" + subFolder + "/" + image;
+        }
+        protected string GetBannerUrl(object row)
+        {
+            DataRowView drv = row as DataRowView;
+            if (drv == null)
+            {
+                return string.Empty;
+            }
+            if (drv.Row.Table.Columns.Contains("IsShowBackButton") && drv["IsShowBackButton"] != DBNull.Value)
+            {
+                bool isShowBackButton = Convert.ToBoolean(drv["IsShowBackButton"]);
+                if (!isShowBackButton)
+                {
+                    return string.Empty;
+                }
+            }
+            if (drv.Row.Table.Columns.Contains("InformationLink") && drv.Row.Table.Columns.Contains("CategoryLink"))
+            {
+                string slug = Convert.ToString(drv["InformationLink"]).Trim();
+                string cate = Convert.ToString(drv["CategoryLink"]).Trim();
+                if (!string.IsNullOrEmpty(slug) && !string.IsNullOrEmpty(cate))
+                {
+                    if (ResManager.CurrentLanguageID == 2)
+                    {
+                        return "/en/" + cate + "/" + slug;
+                    }
+                    return "/" + cate + "/" + slug;
+                }
+            }
+            string[] cols = { "Url", "Link", "BannerUrl" };
+            foreach (string c in cols)
+            {
+                if (drv.Row.Table.Columns.Contains(c) && !string.IsNullOrEmpty(Convert.ToString(drv[c])))
+                {
+                    string url = Convert.ToString(drv[c]);
+                    if (!url.StartsWith("http") && !url.StartsWith("/"))
+                    {
+                        url = DCore.Globals.ApplicationVRoot + "/" + url.TrimStart('/');
+                    }
+                    return url;
+                }
+            }
+            return string.Empty;
+        }
+        protected string GetBannerTitle(object row)
+        {
+            DataRowView drv = row as DataRowView;
+            if (drv == null)
+            {
+                return string.Empty;
+            }
+            string[] cols = { "Title", "Name", "BannerTitle" };
+            foreach (string c in cols)
+            {
+                if (drv.Row.Table.Columns.Contains(c) && !string.IsNullOrEmpty(Convert.ToString(drv[c])))
+                {
+                    return Convert.ToString(drv[c]);
+                }
+            }
+            return string.Empty;
+        }
+        protected string GetBannerItem(object row)
+        {
+            string imageUrl = GetBannerImageUrl(row);
+            string url = GetBannerUrl(row);
+            string title = GetBannerTitle(row);
+            if (string.IsNullOrEmpty(imageUrl))
+            {
+                return string.Empty;
+            }
+            string img = GetBannerImage(imageUrl, title);
+            if (!string.IsNullOrEmpty(url))
+            {
+                return string.Format("<a href=\"{0}\" title=\"{1}\">{2}</a>", url, HttpUtility.HtmlAttributeEncode(title), img);
+            }
+            return img;
         }
     }
 }
